### S3Client with custom endpoint and forcePathStyle

Source: https://github.com/aws/aws-sdk-js-v3/blob/main/clients/client-s3/test/unit/S3.spec.ts

Unit test demonstrating MinIO-compatible S3 client configuration using custom endpoint URL and forcePathStyle, which puts the bucket name in the path (host/bucket/key) instead of the subdomain.

```typescript
describe("endpoint", () => {
  it("users can override endpoint from client.", async () => {
    const endpointValidator: SerializeMiddleware<any, any> = (next) => (args) => {
      const request = args.request as HttpRequest;
      expect(request.protocol).to.equal("http:");
      expect(request.hostname).to.equal("localhost");
      expect(request.port).to.equal(8080);
      expect(request.path).to.equal("/path/bucket/key");
      return Promise.resolve({ output: {} as any, response: {} as any });
    };
    const client = new S3({
      endpoint: "http://localhost:8080/path",
      forcePathStyle: true,
      region: "us-west-2",
      credentials: {
        accessKeyId: "CLIENT_TEST",
        secretAccessKey: "CLIENT_TEST",
      },
    });

    client.middlewareStack.add(endpointValidator, {
      step: "serialize",
      name: "endpointValidator",
      priority: "low",
    });
    return await client.putObject({
      Bucket: "bucket",
      Key: "key",
      Body: "body",
    });
  });
});
```

